from .trainer_state import TrainerState


TRAINER_STATE_METADATA_KEY = "trainer_state"


def attach_trainer_state(metadata: dict, state: TrainerState) -> dict:
	result = dict(metadata)
	result[TRAINER_STATE_METADATA_KEY] = state.serialize()
	return result


def extract_trainer_state(metadata: dict) -> TrainerState | None:
	payload = metadata.get(TRAINER_STATE_METADATA_KEY)
	if payload is None:
		return None

	return TrainerState.deserialize(payload)

from poker.solver.trainer_state import TrainerState
from poker.solver.trainer_state_checkpoint_bridge import (
	extract_trainer_state,
	attach_trainer_state,
)


def test_trainer_state_checkpoint_metadata_round_trip():
	state = TrainerState(global_step=42, payload={"loss": 1.5})

	metadata = attach_trainer_state({}, state)
	restored = extract_trainer_state(metadata)

	assert restored == state
